  .cell:nth-child(n+46):nth-child(-n+54){border-bottom:2px solid var(--line)}
  .cell:hover{background:rgba(18,137,122,.10)}
  .cell.given{color:var(--ink);font-weight:700}
  .cell.user{color:var(--user);font-weight:600}
  .cell.peer{background:rgba(18,137,122,.075)}
  .cell.wrong{color:var(--verm);background:rgba(201,69,47,.11)}
  .cell.wrong::after{
    content:"";position:absolute;top:5px;right:5px;width:5px;height:5px;
    border-radius:50%;background:var(--verm);box-shadow:0 0 0 2px rgba(201,69,47,.22);
  }
  .cell.same{background:rgba(227,161,58,.24)}
  .cell.hintcell{background:rgba(227,161,58,.16)}
  .cell.sel{background:rgba(18,137,122,.22);box-shadow:inset 0 0 0 2px var(--teal)}
  .cell .val{position:relative;z-index:1}
  .cell.pop .val{animation:pop .34s cubic-bezier(.2,1.6,.4,1)}
  @keyframes pop{0%{transform:scale(.4);opacity:.2}60%{transform:scale(1.28)}100%{transform:none;opacity:1}}
  .cell.shake{animation:shake .4s ease}
  @keyframes shake{0%,100%{transform:none}20%{transform:translateX(-3px)}40%{transform:translateX(3px)}60%{transform:translateX(-2px)}80%{transform:translateX(2px)}}
  .notes{
    position:absolute;inset:4px;display:none;
    grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(3,1fr);
    font-family:var(--body);font-size:calc(var(--cell)*.20);font-weight:700;
    color:var(--ink-soft);pointer-events:none;
  }
  .cell.hasnotes .notes{display:grid}
  .notes i{display:flex;align-items:center;justify-content:center;font-style:normal;visibility:hidden}

  .status{
    margin:14px 0 2px;font-size:13px;letter-spacing:.04em;color:var(--ink-soft);
    display:flex;align-items:center;gap:8px;min-height:20px;
  }
  .status b{color:var(--verm)}
  .status .dot{width:7px;height:7px;border-radius:50%;background:var(--teal);flex:0 0 auto;
    animation:blink 2.4s ease-in-out infinite}
  @keyframes blink{0%,100%{opacity:1}50%{opacity:.25}}

  .board.busy{opacity:.45;pointer-events:none;filter:saturate(.4)}
  .board.won .cell{animation:wave .65s ease both;animation-delay:calc(var(--w)*70ms)}
  @keyframes wave{35%{background:rgba(18,137,122,.34);transform:translateY(-4px)}100%{transform:none}}

  /* ---------- overlay ---------- */
  .overlay{
    position:absolute;inset:0;display:grid;place-items:center;z-index:5;
    background:rgba(9,22,25,.82);opacity:0;pointer-events:none;transition:opacity .45s ease;
  }
  .overlay.show{opacity:1;pointer-events:auto}
  .wincard{
    background:var(--paper);color:var(--ink);padding:26px 30px 24px;width:min(92%,340px);
    text-align:center;position:relative;transform:translateY(14px) scale(.96);
    transition:transform .45s cubic-bezier(.2,1.5,.4,1);
    box-shadow:0 24px 50px -18px rgba(0,0,0,.7);
  }
  .overlay.show .wincard{transform:none}
  .wincard h2{font-family:var(--display);font-size:38px;margin:0 0 6px;font-weight:400;letter-spacing:-.02em}
  .wincard p{margin:0 0 16px;font-size:14px;color:var(--ink-soft);line-height:1.5}
  .wincard p b{color:var(--ink);font-family:var(--mono);font-size:13px}
  .stamp{
    position:absolute;top:-14px;right:-10px;transform:rotate(11deg);
    font-family:var(--display);font-size:13px;letter-spacing:.24em;text-transform:uppercase;
    color:var(--verm);border:2px double var(--verm);padding:6px 10px;background:rgba(238,241,236,.9);
    animation:stampIn .5s cubic-bezier(.2,1.7,.4,1) .25s backwards;
  }
  @keyframes stampIn{from{transform:rotate(11deg) scale(2.4);opacity:0}to{transform:rotate(11deg) scale(1);opacity:1}}
  .nextdiff{display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin-bottom:14px}

  /* ---------- panel ---------- */
  .panel{display:grid;gap:14px;align-content:start}
  .card{
    background:linear-gradient(160deg,var(--desk-2),#102426);
    border:1px solid rgba(255,255,255,.09);border-radius:3px;padding:16px 18px 18px;
    box-shadow:0 18px 34px -22px rgba(0,0,0,.8);
  }
  .card h2{
    font-family:var(--display);font-size:12px;font-weight:400;margin:0 0 14px;
    letter-spacing:.28em;text-transform:uppercase;color:var(--amber);
    padding-bottom:8px;border-bottom:1px solid rgba(255,255,255,.09);
  }
  .stats{display:grid;grid-template-columns:1fr 1fr;gap:12px 10px;margin:0}
  .stats div{display:grid;gap:2px}
  .stats dt{font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:#7fa099}
  .stats dd{margin:0;font-family:var(--display);font-size:27px;line-height:1;color:#eaf3ef;font-variant-numeric:tabular-nums}
  .stats dd.warn{color:var(--verm)}
  #statTime{font-family:var(--mono);font-size:22px;letter-spacing:.02em}
  .progress{height:6px;background:rgba(255,255,255,.09);border-radius:99px;overflow:hidden;margin-top:16px}
  .progress span{
    display:block;height:100%;width:0%;border-radius:99px;
    background:linear-gradient(90deg,var(--teal),var(--mint),var(--amber));
    transition:width .55s cubic-bezier(.2,.8,.2,1);
  }
  .proglab{margin:8px 0 0;font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:#7fa099}

  .numpad{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
  .key{
    position:relative;font-family:var(--display);font-size:26px;line-height:1;
    padding:12px 0 14px;color:#f0f6f3;cursor:pointer;border-radius:3px;
    background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.12);
    transition:transform .16s cubic-bezier(.2,.8,.2,1),background .16s,color .16s,box-shadow .16s;
  }
  .key sup{
    font-family:var(--body);font-size:10px;font-weight:700;vertical-align:super;
    color:var(--amber);margin-left:3px;letter-spacing:0;
  }
  .key:hover{background:rgba(18,137,122,.30);transform:translateY(-2px);box-shadow:0 8px 16px -8px rgba(0,0,0,.8)}
  .key:active{transform:translateY(0) scale(.96)}
  .key.done{opacity:.28;pointer-events:none}
  .key.done sup{color:#7fa099}

  .tools{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}
  .tool{
    font:inherit;font-size:12.5px;letter-spacing:.06em;text-transform:uppercase;
    padding:10px 8px;border-radius:3px;cursor:pointer;color:#cfe3dd;
    background:transparent;border:1px solid rgba(255,255,255,.14);
    transition:background .16s,color .16s,transform .16s,border-color .16s;
  }
  .tool:hover{background:rgba(255,255,255,.07);transform:translateY(-1px);border-color:var(--mint);color:#fff}
  .tool:active{transform:none}
  .tool.is-on{background:var(--amber);border-color:var(--amber);color:#1a1205;font-weight:700}

  .cta{
    font:inherit;font-size:14px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;
    padding:15px 18px;border:0;border-radius:3px;cursor:pointer;color:#1a1205;width:100%;
    background:linear-gradient(150deg,#f0b64f,var(--amber));
    box-shadow:0 14px 26px -14px rgba(227,161,58,.85);
    transition:transform .18s cubic-bezier(.2,.8,.2,1),box-shadow .18s;
  }
  .cta:hover{transform:translateY(-3px);box-shadow:0 20px 34px -14px rgba(227,161,58,.95)}
  .cta:active{transform:translateY(0)}

  .legend{display:grid;gap:7px;font-size:12.5px;color:#9dbab4}
  .legend div{display:flex;justify-content:space-between;gap:10px;align-items:center}
  kbd{
    font-family:var(--mono);font-size:11px;padding:3px 7px;border-radius:3px;
    background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.14);color:#e6f1ed;
    box-shadow:0 1px 0 rgba(0,0,0,.4);white-space:nowrap;
  }
  footer{
    margin-top:clamp(22px,3vw,38px);padding-top:14px;border-top:1px solid rgba(255,255,255,.1);
    font-size:12px;letter-spacing:.05em;color:#6f8f89;display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;
  }
  :focus-visible{outline:2px solid var(--amber);outline-offset:2px}

  @media (max-width:900px){
    .play{grid-template-columns:1fr}
    .masthead{align-items:flex-start}
    .edition{justify-items:flex-start;text-align:left}
    .diffs{justify-content:flex-start}
  }
  @media (prefers-reduced-motion:reduce){
    *{animation-duration:.001ms!important;animation-delay:0ms!important;transition-duration:.001ms!important}
  }
</style>
</head>
<body>

<div class="ambient" aria-hidden="true">
  <span style="top:4%;left:-2%">7</span>
  <span style="top:38%;right:-3%">3</span>
  <span style="bottom:-6%;left:22%">9</span>
  <span style="top:60%;right:26%">1</span>
</div>

<main class="sheet">

  <header class="masthead">
    <div class="brand">
      <div class="mark" aria-hidden="true">
        <i class="hot">4</i><i></i><i>7</i><i></i><i class="hot2">1</i><i></i><i>9</i><i></i><i class="hot">5</i>
      </div>
      <div>
        <span class="kicker">Logica pura · carta &amp; matita</span>
        <h1>SUD<em>O</em>KU<sup>9×9</sup></h1>
        <p class="rules">Ogni riga, ogni colonna e ogni riquadro <b>3×3</b> deve contenere le cifre dal <b>1</b> al <b>9</b>, <b>una sola volta</b>. Un'unica soluzione per griglia.</p>
      </div>
    </div>
    <div class="edition">
      <div class="num">Tavola n. <span id="puzzleNo">0000</span></div>
      <div class="diffs" role="group" aria-label="Livello di difficoltà">
        <button class="pill is-on" data-diff="facile">Facile</button>
        <button class="pill" data-diff="media">Media</button>
        <button class="pill" data-diff="difficile">Difficile</button>
      </div>
    </div>
  </header>

  <div class="play">

    <section class="boardwrap">
      <span class="crop tl"></span><span class="crop tr"></span>
      <span class="crop bl"></span><span class="crop br"></span>
      <div class="board" id="board" role="grid" aria-label="Griglia di sudoku"></div>
      <p class="status" id="status" aria-live="polite"><span class="dot"></span><span id="statusText">Preparo la griglia…</span></p>
      <div class="overlay" id="overlay">
        <div class="wincard">
          <div class="stamp">Validato</div>
          <h2>Risolto.</h2>
          <p id="winText">Griglia completa.</p>
          <div class="nextdiff">
            <button class="pill" data-diff="facile">Facile</button>
            <button class="pill" data-diff="media">Media</button>
            <button class="pill" data-diff="difficile">Difficile</button>
          </div>
          <button class="cta" id="btnNew2">Nuova partita</button>
        </div>
      </div>
    </section>

    <aside class="panel">

      <div class="card">
        <h2>La partita</h2>
        <dl class="stats">
          <div><dt>Livello</dt><dd id="statDiff">Facile</dd></div>
          <div><dt>Tempo</dt><dd id="statTime">0:00</dd></div>
          <div><dt>Errori</dt><dd id="statErr">0</dd></div>
          <div><dt>Suggerimenti</dt><dd id="statHint">0</dd></div>
        </dl>
        <div class="progress"><span id="bar"></span></div>
        <p class="proglab"><span id="progPct">0</span>% completato</p>
      </div>

      <div class="card">
